sections.code:
Bind slides:data with alias promotion and an active-template location key.

<section>
  {{#promotion.items}}
    <figure>
      <img src="{{image}}" alt="{{alt}}" loading="lazy">
      <figcaption>{{title}} — {{text}}</figcaption>
    </figure>
  {{/promotion.items}}
  {{^promotion.items}}<p>No slides match this page.</p>{{/promotion.items}}
</section>
